"""Import/export flows as JSON – e.g. generated by an AI.

Format (deliberately tolerant, so that LLM output fits without rework):

    {
      "flows": [                                    # also "automatisierungen", or a list directly
        {
          "name": "Flurlicht bei Bewegung",
          "description": "...",
          "enabled": false,
          "nodes": [
            {"id": "n1", "type": "device_state", "x": 0, "y": 0,
             "config": {"role": "trigger", "target": {"devices": ["flur_sensor"]}, "prop": "motion", "is": "yes",
                        "hold_off": 120}},
            {"id": "n2", "type": "when", "x": 280, "y": 0, "config": {"match": "all"}},
            {"id": "n3", "type": "time", "x": 0, "y": 160, "config": {"role": "condition", "from": "sunset", "to": "sunrise"}},
            {"id": "n4", "type": "set_device", "x": 560, "y": 0,
             "config": {"do": "switch", "target": {"devices": ["flur_licht"]}, "to": "on"}},
            {"id": "n5", "type": "set_device", "x": 560, "y": 160,
             "config": {"do": "switch", "target": {"devices": ["flur_licht"]}, "to": "off"}}
          ],
          "edges": [
            {"from": "n1", "fromPort": "out", "to": "n2", "toPort": "in"},
            {"from": "n3", "fromPort": "val", "to": "n2", "toPort": "c1"},
            {"from": "n2", "fromPort": "yes", "to": "n4", "toPort": "in"},
            {"from": "n1", "fromPort": "end", "to": "n5", "toPort": "in"}
          ]
        }
      ]
    }

Role: nodes with roles are a trigger with "role": "trigger" (signal outputs, e.g. out/end) and a condition with
"role": "condition" (output val). Conditions attach to the inputs c1, c2 … of "Wenn / Dann".
If a flow with the same name already exists, it is replaced; otherwise created. Unknown nodes are an error.
"""
from __future__ import annotations

from typing import Any

from . import flow_catalog, flows_store

MAX_FLOWS = 20


class ImportError_(ValueError):
    """The import file is unusable – the text is meant for the user."""
    pass


def _flow_list(doc: Any) -> list[Any]:
    """List of the flows from an import file: {"flows": [...]}, a bare list or a single flow."""
    if isinstance(doc, dict):
        for k in ("flows", "automatisierungen", "automations"):
            if isinstance(doc.get(k), list):
                return doc[k]
        if "nodes" in doc or "name" in doc:
            return [doc]
    if isinstance(doc, list):
        return doc
    raise ImportError_("Keine Flows gefunden (erwartet: {\"flows\": [...]})")


def _edges(raw: Any) -> list[dict]:
    """Schreibweisen vereinheitlichen, die Sprachmodelle gern liefern (from_port, von/nach …)."""
    out = []
    for e in raw if isinstance(raw, list) else []:
        if isinstance(e, dict):
            out.append({"id": e.get("id"), "from": e.get("from") or e.get("von"),
                        "fromPort": e.get("fromPort") or e.get("from_port") or e.get("ausgang"),
                        "to": e.get("to") or e.get("nach") or e.get("zu"),
                        "toPort": e.get("toPort") or e.get("to_port") or e.get("eingang")})
    return out


def plan(doc: Any, existing: dict[str, str]) -> dict[str, Any]:
    """Check a file and map it onto ComfyOS without changing anything. existing: flow id -> name."""
    ex_by_name = {v.strip().casefold(): k for k, v in existing.items()}
    raw_flows = _flow_list(doc)
    if len(raw_flows) > MAX_FLOWS:
        raise ImportError_(f"Höchstens {MAX_FLOWS} Flows pro Datei")
    out: list[dict[str, Any]] = []
    for i, f in enumerate(raw_flows):
        if not isinstance(f, dict):
            raise ImportError_(f"Flow {i + 1} ist kein Objekt")
        name = " ".join(str(f.get("name") or f.get("bezeichnung") or "").split())[:60]
        raw_nodes = f.get("nodes") or f.get("knoten") or []
        raw_edges = _edges(f.get("edges") or f.get("verbindungen") or [])
        nodes, edges = flows_store.clean_graph(raw_nodes, raw_edges)
        errors = [f"Unbekannter Baustein „{t}“" for t in flow_catalog.unknown_types(nodes)]
        warnings: list[str] = []
        if isinstance(raw_nodes, list) and len(nodes) < len(raw_nodes):
            warnings.append(f"{len(raw_nodes) - len(nodes)} Bausteine ohne Typ oder über der Höchstzahl wurden übersprungen")
        if len(edges) < len(raw_edges):
            warnings.append(f"{len(raw_edges) - len(edges)} Verbindungen unvollständig oder doppelt – übersprungen")
        if not errors:
            edges, notes = flow_catalog.normalize(nodes, edges)
            warnings += list(dict.fromkeys(notes))
        entry: dict[str, Any] = {
            "name": name or f"Flow {i + 1}",
            "description": " ".join(str(f.get("description") or f.get("beschreibung") or "").split())[:200],
            "enabled": bool(f.get("enabled") or f.get("aktiv") or False),
            "flow_id": ex_by_name.get(name.strip().casefold()),
            "warnings": warnings, "errors": errors,
            "node_count": len(nodes), "edge_count": len(edges), "nodes": nodes, "edges": edges,
        }
        entry["action"] = "update" if entry["flow_id"] else "create"
        out.append(entry)
    ok = all(not e["errors"] for e in out) and any(e["node_count"] > 0 for e in out)
    return {"flows": out, "ok": ok}


def export_flows(flows: list[dict[str, Any]]) -> dict[str, Any]:
    """Return existing flows in the import format (outdated flows are left out)."""
    out = []
    for f in flows:
        if flows_store.outdated(f):
            continue
        out.append({
            "name": f.get("name") or "",
            "description": f.get("description") or "",
            "enabled": bool(f.get("enabled")),
            "nodes": [{"id": n["id"], "type": n["type"], "x": n.get("x", 0), "y": n.get("y", 0),
                       "config": {k: v for k, v in (n.get("config") or {}).items() if k != "token"}}
                      for n in f.get("nodes") or []],
            "edges": [{"id": e["id"], "from": e["from"], "fromPort": e["fromPort"],
                       "to": e["to"], "toPort": e["toPort"]} for e in f.get("edges") or []],
        })
    return {"flows": out}
